<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';
import {api,apiMessage} from '@/api/client';
import {useAuthStore} from '@/stores/auth';
import {requiresConnection} from '@/connectionState';
import AppSheet from '@/components/AppSheet.vue';
import type {PageResponse} from '@/types';
interface Policy{keepNewest:number;retentionDays:number;backupMaxHours:number;diskMinPercent:number;version:number}
interface Proof{backupName:string|null;verifiedAt:string|null;verified:boolean}
interface Status{enabled:boolean;mailAlertsEnabled:boolean;dataAvailable:boolean;observedAt:string|null;policy:Policy;checks:{code:string;message:string;ok:boolean}[];backups:{name:string;completedAt:string;bytes:number;localVerified:boolean}[];cleanupPreview:{name:string;candidate:boolean;reason:string}[];oss:Proof;restore:Proof;diskFreeBytes:number;diskTotalBytes:number}
interface Member{id:string;email:string;displayName:string;role:string;enabled:boolean;version:number}
const auth=useAuthStore(),tab=ref('STATUS'),status=ref<Status|null>(null),busy=ref(false),error=ref(''),notice=ref(''),alerts=ref<Record<string,unknown>[]>([]);
const policy=reactive<Policy>({keepNewest:7,retentionDays:30,backupMaxHours:26,diskMinPercent:15,version:0});
const governance=ref(false),members=ref<PageResponse<Member>|null>(null),memberPage=ref(0),search=ref(''),audit=ref<PageResponse<Record<string,unknown>>|null>(null),auditPage=ref(0);
const policyAudit=ref<PageResponse<Record<string,unknown>>|null>(null),policyAuditPage=ref(0);
const target=ref<Member|null>(null),reason=ref(''),confirmed=ref(false);
function time(value:unknown){return value?new Date(value as string).toLocaleString('zh-CN'):'暂无可验证记录';}
async function run(action:()=>Promise<void>){if(busy.value||requiresConnection())return;busy.value=true;error.value='';notice.value='';try{await action();}catch(e){error.value=apiMessage(e);}finally{busy.value=false;}}
async function loadStatus(){status.value=(await api.get<Status>('/admin/operations/status')).data;Object.assign(policy,status.value.policy);alerts.value=(await api.get<Record<string,unknown>[]>('/admin/operations/alerts')).data;}
async function loadMembers(){members.value=(await api.get<PageResponse<Member>>('/admin/governance/members',{params:{page:memberPage.value,size:10,search:search.value}})).data;}
async function loadPolicyAudit(){policyAudit.value=(await api.get<PageResponse<Record<string,unknown>>>('/admin/operations/policy-audit',{params:{page:policyAuditPage.value}})).data;}
async function loadAudit(){audit.value=(await api.get<PageResponse<Record<string,unknown>>>('/admin/governance/audit',{params:{page:auditPage.value,size:10}})).data;await loadPolicyAudit();}
async function load(){await loadStatus();governance.value=(await api.get<{enabled:boolean}>('/admin/governance/config')).data.enabled;await loadMembers();await loadAudit();}
async function refresh(){await run(load);}
async function evaluate(){await run(async()=>{alerts.value=(await api.post<Record<string,unknown>[]>('/admin/operations/evaluate')).data;await loadStatus();notice.value='站内状态已核对，相同故障复用同一事件，不发送邮件、不执行清理。';});}
async function savePolicy(){await run(async()=>{Object.assign(policy,(await api.put<Policy>('/admin/operations/policy',policy)).data);await loadStatus();await loadPolicyAudit();notice.value='只更新了预览规则并记录审计，没有删除文件。';});}
function openMember(member:Member){target.value=member;reason.value='';confirmed.value=false;error.value='';}
async function changeMember(){const member=target.value;if(!member||!confirmed.value||!governance.value)return;await run(async()=>{await api.put(`/admin/governance/members/${member.id}`,{enabled:!member.enabled,version:member.version,reason:reason.value});target.value=null;await loadMembers();await loadAudit();notice.value=member.enabled?'成员已停用；下一次联网请求将被拒绝，旧会话已撤销。':'成员已恢复；需要重新登录，旧令牌不会复活。';});}
async function searchMembers(){memberPage.value=0;await run(loadMembers);}
async function moveMember(delta:number){memberPage.value+=delta;await run(loadMembers);}
async function moveAudit(delta:number){auditPage.value+=delta;await run(loadAudit);}
async function movePolicyAudit(delta:number){policyAuditPage.value+=delta;await run(loadPolicyAudit);}
onMounted(()=>{if(auth.user?.role==='ADMIN')void refresh();});
</script>
<template><div class="page operations-page"><header class="page-head"><div><h1>运行与成员治理</h1><p>只展示运行证据和必要账号状态，不读取成员的私人计划、AI 对话或备份正文。</p></div><button class="btn" :disabled="busy||requiresConnection()" @click="refresh">重新读取状态</button></header>
  <p v-if="auth.user?.role!=='ADMIN'" role="alert">只有管理员可以查看此页面。</p><template v-else><p v-if="error" class="error-text" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="requiresConnection()" class="helper-text">本页需要联网，不使用私人数据缓存，不将管理操作加入离线队列。</p>
  <nav class="button-row" aria-label="治理功能"><button v-for="(label,key) in {STATUS:'运行状态',POLICY:'保留预览',MEMBERS:'成员状态',AUDIT:'成员审计'}" :key="key" class="btn" :aria-pressed="tab===key" @click="tab=key">{{label}}</button></nav>
  <section v-if="tab==='STATUS'&&status" class="section"><h2>备份与主机状态</h2><p>{{status.enabled?'运维采集已启用':'运维采集尚未启用'}} · {{status.dataAvailable?'状态证据可读取':'状态未知，不能当作正常'}} · 采集时间 {{time(status.observedAt)}}</p><p>邮件告警未启用；必须另外确认收件人和真实发送验收。页面刷新不会自动发送邮件或删除文件。</p><article v-for="check in status.checks" :key="check.code" class="check-row"><strong>{{check.ok?'已核对':'需要关注'}}</strong><p>{{check.message}}</p></article><dl><dt>最近 OSS 下载校验</dt><dd>{{time(status.oss.verifiedAt)}} · {{status.oss.verified?'有对应文件证据':'尚未验证'}}<span v-if="status.oss.backupName"> · {{status.oss.backupName}}</span></dd><dt>最近独立恢复演练</dt><dd>{{time(status.restore.verifiedAt)}} · {{status.restore.verified?'有全表比较证据':'尚未验证'}}<span v-if="status.restore.backupName"> · {{status.restore.backupName}}</span></dd><dt>备份目录所在磁盘</dt><dd>{{status.diskFreeBytes<0?'未知':(status.diskFreeBytes/1073741824).toFixed(1)+' GiB 可用 / '+(status.diskTotalBytes/1073741824).toFixed(1)+' GiB 总计'}}</dd></dl><button class="btn" :disabled="busy||!status.enabled||requiresConnection()" @click="evaluate">核对并记录站内告警</button><h3>去重事件</h3><article v-for="item in alerts" :key="String(item.code)" class="record-row"><strong>{{item.code}} · {{item.active?'待处理':'已恢复'}}</strong><p>首次 {{time(item.first_seen)}} · 最近 {{time(item.last_seen)}}</p></article><p v-if="!alerts.length">尚未记录告警事件；不代表采集已经启用或备份正常。</p></section>
  <section v-if="tab==='POLICY'&&status" class="section"><h2>只预览，不执行删除</h2><p>范围仅为受管 MySQL 备份清单，不包含签名密钥、旧发布、数据库卷或其他目录。唯一恢复点、近期备份及校验／演练不明的文件均保留。</p><form @submit.prevent="savePolicy"><div class="form-grid"><label>至少保留最近份数<input v-model.number="policy.keepNewest" type="number" min="2" max="100" required/></label><label>保留天数<input v-model.number="policy.retentionDays" type="number" min="7" max="3650" required/></label><label>备份最长间隔（小时）<input v-model.number="policy.backupMaxHours" type="number" min="6" max="168" required/></label><label>磁盘最低可用比例（%）<input v-model.number="policy.diskMinPercent" type="number" min="5" max="80" required/></label></div><button class="btn primary" :disabled="busy||requiresConnection()">只保存预览规则</button></form><p v-if="!status.cleanupPreview.length">暂无可验证清单，未生成删除建议。</p><article v-for="item in status.cleanupPreview" :key="item.name" class="record-row"><strong>{{item.name}}</strong><p>{{item.candidate?'候选建议，未删除':'受保护'}}：{{item.reason}}</p></article></section>
  <section v-if="tab==='MEMBERS'" class="section"><h2>成员停用与恢复</h2><p>{{governance?'成员治理开关已启用。':'成员治理开关关闭：先确认停用和令牌策略，再由维护者启用。当前不能执行停用／恢复。'}}</p><p>启用后，停用在下一次联网请求生效并撤销刷新会话；恢复须重新登录，旧令牌不复活。不会远程删除设备内容，离线缓存身份仍按原 24 小时边界处理。不能在此停用自己或管理员。</p><form class="search-row" @submit.prevent="searchMembers"><label>搜索成员<input v-model="search" maxlength="190" placeholder="邮箱或显示名称"/></label><button class="btn" :disabled="busy">查询成员</button></form><article v-for="member in members?.content??[]" :key="member.id" class="member-row"><div><h3>{{member.displayName}}</h3><p>{{member.email}}</p><small>{{member.role==='ADMIN'?'管理员':'普通成员'}} · {{member.enabled?'可登录':'已停用'}}</small></div><button v-if="member.role==='USER'" class="btn" :disabled="busy||!governance||requiresConnection()" @click="openMember(member)">{{member.enabled?'停用成员':'恢复成员'}}</button></article><footer v-if="members" class="pagination-bar"><span>第 {{memberPage+1}} 页 · 共 {{members.totalElements}} 人</span><button class="btn" :disabled="busy||memberPage===0" @click="moveMember(-1)">上一页成员</button><button class="btn" :disabled="busy||memberPage+1>=members.totalPages" @click="moveMember(1)">下一页成员</button></footer></section>
  <section v-if="tab==='AUDIT'" class="section"><h2>成员状态操作记录</h2><p>仅包含操作者、目标编号、原因及时间，不包含成员计划或会话凭据。</p><article v-for="item in audit?.content??[]" :key="String(item.id)" class="record-row"><strong>{{item.action==='DISABLE'?'停用':'恢复'}} · {{time(item.created_at)}}</strong><p>成员 {{item.target_id}} · 管理员 {{item.actor_id}}</p><p>{{item.reason}}</p></article><p v-if="audit&&!audit.totalElements">暂无操作记录。</p><footer v-if="audit" class="pagination-bar"><span>共 {{audit.totalElements}} 条</span><button class="btn" :disabled="busy||auditPage===0" @click="moveAudit(-1)">上一页审计</button><button class="btn" :disabled="busy||auditPage+1>=audit.totalPages" @click="moveAudit(1)">下一页审计</button></footer><h3>运维规则审计</h3><article v-for="item in policyAudit?.content??[]" :key="String(item.id)" class="record-row"><strong>{{time(item.created_at)}} · 版本 {{item.previous_version}} → {{item.new_version}}</strong><details><summary>查看规则前后内容</summary><p>变更前</p><pre>{{item.before_json}}</pre><p>变更后</p><pre>{{item.after_json}}</pre></details></article><footer v-if="policyAudit" class="pagination-bar"><span>共 {{policyAudit.totalElements}} 条规则记录</span><button class="btn" :disabled="busy||policyAuditPage===0" @click="movePolicyAudit(-1)">上一页规则记录</button><button class="btn" :disabled="busy||policyAuditPage+1>=policyAudit.totalPages" @click="movePolicyAudit(1)">下一页规则记录</button></footer></section>
  <AppSheet :open="!!target" title="确认成员状态变更" title-id="governance-change-title" :busy="busy" @close="target=null"><form class="member-editor" @submit.prevent="changeMember"><p v-if="error" class="error-text" role="alert">{{error}}</p><h2>{{target?.displayName}}</h2><p>{{target?.email}}</p><p>{{target?.enabled?'此成员的联网请求和旧会话将失效；不删除计划或本机草稿。':'此成员可重新登录；旧令牌和旧刷新会话不会恢复。'}}</p><label>变更原因<textarea v-model="reason" required maxlength="500" rows="4" placeholder="简要说明原因，不填写密码或私人计划内容。"/></label><label class="confirm-check"><input v-model="confirmed" type="checkbox"/>我已确认目标账号与影响，执行本次状态变更。</label><button class="btn primary" :disabled="busy||!confirmed||!reason.trim()||!governance">确认变更成员状态</button></form></AppSheet>
  </template></div></template>
<style scoped>
.operations-page>.button-row{margin-bottom:24px}.operations-page [aria-pressed=true]{background:#002fa7;color:#fff}.operations-page .section{padding:24px;margin:24px 0}.operations-page label,.operations-page form{display:grid;gap:12px}.operations-page form{margin:20px 0}.check-row{display:flex;gap:20px;border-top:1px solid #d8d8df;padding:16px 0;align-items:center}.check-row strong{color:#002fa7;flex-shrink:0}.operations-page dd{margin:8px 0 20px;overflow-wrap:anywhere}.operations-page dt{font-weight:700}.record-row,.member-row{border-top:1px solid #d8d8df;padding:20px 0;overflow-wrap:anywhere}.member-row{display:flex;align-items:center;justify-content:space-between;gap:16px}.member-row>div{min-width:0}.operations-page .search-row{grid-template-columns:1fr auto;align-items:end}.member-editor{display:grid;gap:18px}.member-editor label{display:grid;gap:10px}.member-editor .confirm-check{display:flex;align-items:start}.confirm-check input{width:20px;height:20px;min-height:20px;flex:0 0 20px;accent-color:#002fa7}.operations-page .pagination-bar{flex-wrap:wrap;gap:12px}
@media(max-width:700px){.operations-page .section{padding:16px}.operations-page>.button-row .btn{flex:1 1 40%}.operations-page .form-grid,.operations-page .search-row{grid-template-columns:minmax(0,1fr)}.member-row{align-items:start}.check-row{display:grid;gap:8px}.operations-page input{min-width:0;max-width:100%}}
</style>
